/**
 * PYYNE PLAYBOOK — Renderer
 * =========================================
 * Reads PLAYBOOK_CONFIG and builds the full site DOM.
 * Do not edit this file to change content — edit content/config.js instead.
 */

/* ── SVG Icons ─────────────────────────────────────── */
